import { useUser } from "./hooks/useUser"

export default function UsersPage() {
    const user = useUser(1)

    if(user.isLoading) return <p>Data is loading....</p>

    if(user.isError) return <p>{user.isError}</p>

    return (
    <div>
        <h1>Users Page</h1>
    </div>
   )
}
